{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    sum_min = sum(s['minimum'] for s in segments)
    sum_cap = sum(s['capacity'] for s in segments)
    if budget < sum_min:
        return {'error': 'budget below sum of minima'}
    if budget > sum_cap:
        return {'error': 'budget above total capacity'}
    alloc = {s['name']: s['minimum'] for s in segments}
    total = sum_min
    while total < budget:
        best = None
        best_val = -1.0
        for s in segments:
            name = s['name']
            imp = s['importance']
            next_pos = alloc[name] + 1
            if next_pos > s['capacity']:
                continue
            val = imp / next_pos
            if val > best_val:
                best_val = val
                best = name
        if best is None:
            break
        alloc[best] += 1
        total += 1
    return {
        'allocations': alloc,
        'name_mapping': [s['name'] for s in segments],
        'conserved_total': total
    }"
}
